// Writes lib/contract.ts: every type alias exported by contract-source.ts,
// expanded into a plain type, so the published SDK carries Ajour's contract
// without zod or @ajour/shared. It also copies the broker's request rules,
// packages/shared/plugin-request-rules.ts, to lib/request-rules.ts, so the
// fake matches paths and refuses headers as the broker does. Run it after
// changing either:
//
//   corepack pnpm --filter @ajour/plugin-sdk generate
//
// With --check, it writes nothing and exits 1 when a generated file is stale.
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import prettier from "prettier";
import ts from "typescript";

const packageRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
);
const sourcePath = path.join(packageRoot, "scripts", "contract-source.ts");
const outputPath = path.join(packageRoot, "lib", "contract.ts");
const rulesSourcePath = path.resolve(
  packageRoot,
  "..",
  "shared",
  "plugin-request-rules.ts",
);
const rulesOutputPath = path.join(packageRoot, "lib", "request-rules.ts");

const HEADER = `// Generated by scripts/generate-contract.mjs from Ajour's shared schemas.
// Do not edit: change the schema, then run \`pnpm generate\`.
`;

const RULES_HEADER = `// Copied by scripts/generate-contract.mjs from packages/shared/plugin-request-rules.ts.
// Do not edit: change the shared file, then run \`pnpm generate\`.
`;

function generate() {
  const program = ts.createProgram([sourcePath], {
    strict: true,
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    allowImportingTsExtensions: true,
    noEmit: true,
    skipLibCheck: true,
    types: [],
  });
  const problems = ts.getPreEmitDiagnostics(program);
  if (problems.length > 0) {
    throw new Error(
      ts.formatDiagnostics(problems, {
        getCanonicalFileName: (name) => name,
        getCurrentDirectory: () => packageRoot,
        getNewLine: () => "\n",
      }),
    );
  }
  const checker = program.getTypeChecker();
  const source = program.getSourceFile(sourcePath);
  const moduleSymbol = checker.getSymbolAtLocation(source);
  const blocks = [];
  for (const symbol of checker.getExportsOfModule(moduleSymbol)) {
    const declaration = symbol.declarations?.[0];
    if (!declaration || !ts.isTypeAliasDeclaration(declaration)) continue;
    const text = checker.typeToString(
      checker.getTypeAtLocation(declaration.type),
      undefined,
      ts.TypeFormatFlags.NoTruncation |
        ts.TypeFormatFlags.InTypeAlias |
        ts.TypeFormatFlags.MultilineObjectLiterals,
    );
    if (/\bZod|\bimport\(/.test(text)) {
      throw new Error(`${symbol.name} still names a schema type: ${text}`);
    }
    const docs = ts.displayPartsToString(
      symbol.getDocumentationComment(checker),
    );
    blocks.push(
      `${docs ? `/** ${docs} */\n` : ""}export type ${symbol.name} = ${text};`,
    );
  }
  return `${HEADER}\n${blocks.join("\n\n")}\n`;
}

async function formatted(text, filepath) {
  const config = (await prettier.resolveConfig(filepath)) ?? {};
  return await prettier.format(text, { ...config, filepath });
}

const rulesSource = (await readFile(rulesSourcePath, "utf8")).replaceAll(
  "\r\n",
  "\n",
);
const outputs = [
  [outputPath, await formatted(generate(), outputPath)],
  [
    rulesOutputPath,
    await formatted(`${RULES_HEADER}\n${rulesSource}`, rulesOutputPath),
  ],
];

if (process.argv.includes("--check")) {
  const stale = [];
  for (const [file, generated] of outputs) {
    const current = await readFile(file, "utf8").catch(() => "");
    if (current.replaceAll("\r\n", "\n") !== generated) {
      stale.push(path.relative(packageRoot, file).replaceAll("\\", "/"));
    }
  }
  if (stale.length > 0) {
    process.stderr.write(
      `Stale: ${stale.join(", ")}. Run: corepack pnpm --filter @ajour/plugin-sdk generate\n`,
    );
    process.exit(1);
  }
} else {
  for (const [file, generated] of outputs) await writeFile(file, generated);
}
